[SOURCE_PAYLOAD]
{"id":"cue-1","group_id":"source-speech-v1:cue-1","text":"你敢相信吗"}
{"id":"cue-2","group_id":"source-speech-v1:cue-1","text":"沃尔沃迷人的方向键按键声"}
{"id":"cue-3","group_id":"source-speech-v1:cue-1","text":"居然根本不是程序员写出来的"}
{"id":"cue-4","group_id":"source-speech-v1:cue-1","text":"其他车企做按键音"}
{"id":"cue-5","group_id":"source-speech-v1:cue-1","text":"都是坐在办公室调电脑参数"}
{"id":"cue-6","group_id":"source-speech-v1:cue-1","text":"但沃尔沃的设计师却不这么干"}
{"id":"cue-7","group_id":"source-speech-v1:cue-7","text":"他说"}
{"id":"cue-8","group_id":"source-speech-v1:cue-7","text":"这个按键声"}
{"id":"cue-9","group_id":"source-speech-v1:cue-9","text":"车主要听上弯字"}
{"id":"cue-10","group_id":"source-speech-v1:cue-9","text":"不能刺耳 不能刻意"}
{"id":"cue-11","group_id":"source-speech-v1:cue-9","text":"更不能听久了心烦"}
{"id":"cue-12","group_id":"source-speech-v1:cue-9","text":"哪怕堵在车水马龙里"}
{"id":"cue-13","group_id":"source-speech-v1:cue-9","text":"听到它也能让人心里一静"}
{"id":"cue-14","group_id":"source-speech-v1:cue-9","text":"于是他带着整个团队"}
{"id":"cue-15","group_id":"source-speech-v1:cue-15","text":"扎进深山老林待了整整两天"}
{"id":"cue-16","group_id":"source-speech-v1:cue-15","text":"折断了三百多根不同的树枝"}
{"id":"cue-17","group_id":"source-speech-v1:cue-15","text":"去试每一种木头"}
{"id":"cue-18","group_id":"source-speech-v1:cue-15","text":"每一个粗细在弯折时的声音"}
{"id":"cue-19","group_id":"source-speech-v1:cue-15","text":"一遍又一遍"}
{"id":"cue-20","group_id":"source-speech-v1:cue-15","text":"录下了三百多种大自然的声音"}
{"id":"cue-21","group_id":"source-speech-v1:cue-21","text":"目标只有一个"}
{"id":"cue-22","group_id":"source-speech-v1:cue-21","text":"找到一种"}
{"id":"cue-23","group_id":"source-speech-v1:cue-21","text":"温柔 自然 听一千遍一万遍"}
{"id":"cue-24","group_id":"source-speech-v1:cue-21","text":"也不会烦躁的声响"}
{"id":"cue-25","group_id":"source-speech-v1:cue-21","text":"终于在无数次尝试后"}
{"id":"cue-26","group_id":"source-speech-v1:cue-21","text":"他们找到了"}
{"id":"cue-27","group_id":"source-speech-v1:cue-27","text":"像素树枝轻轻弯折时"}
{"id":"cue-28","group_id":"source-speech-v1:cue-27","text":"那声温柔的嘎之声"}
{"id":"cue-29","group_id":"source-speech-v1:cue-27","text":"后来他们把这段来自大森林的声音数字画"}
{"id":"cue-30","group_id":"source-speech-v1:cue-27","text":"反复调鞋"}
{"id":"cue-31","group_id":"source-speech-v1:cue-27","text":"辅平"}
{"id":"cue-32","group_id":"source-speech-v1:cue-27","text":"才变成了如今窝耳窝方向键独有的点击声"}
{"id":"cue-33","group_id":"source-speech-v1:cue-33","text":"这也是为什么"}
{"id":"cue-34","group_id":"source-speech-v1:cue-33","text":"很多车主都说沃尔沃的按键"}
{"id":"cue-35","group_id":"source-speech-v1:cue-33","text":"是全网最治愈的按键"}
{"id":"cue-36","group_id":"source-speech-v1:cue-33","text":"听到这声来自自然的声音"}
{"id":"cue-37","group_id":"source-speech-v1:cue-33","text":"哪怕外面再堵车"}
{"id":"cue-38","group_id":"source-speech-v1:cue-33","text":"心情再烦躁"}
{"id":"cue-39","group_id":"source-speech-v1:cue-39","text":"也能瞬间被抚平"}
{"id":"cue-40","group_id":"source-speech-v1:cue-39","text":"原来高级感"}
{"id":"cue-41","group_id":"source-speech-v1:cue-39","text":"真的藏在"}
{"id":"cue-42","group_id":"source-speech-v1:cue-39","text":"那些容易被忽视的细节力"}
{"id":"cue-43","group_id":"source-speech-v1:cue-39","text":"你还见过车上"}
{"id":"cue-44","group_id":"source-speech-v1:cue-39","text":"哪些暖心的细节设计吗"}
[/SOURCE_PAYLOAD]

