{"translations":{"cue-1":"Bạn có dám tin không,","cue-2":"tiếng bấm phím điều hướng đầy mê hoặc của Volvo","cue-3":"hoàn toàn không phải do lập trình viên tạo ra?","cue-4":"Khi các hãng xe khác làm âm thanh nút bấm,","cue-5":"họ đều ngồi trong văn phòng điều chỉnh thông số máy tính,","cue-6":"nhưng các nhà thiết kế của Volvo lại không làm như vậy.","cue-7":"Ông nói rằng,","cue-8":"âm thanh nút bấm này,","cue-9":"chủ xe phải nghe hàng chục ngàn lần,","cue-10":"không được chói tai, không được gượng gạo,","cue-11":"lại càng không thể khiến người ta khó chịu khi nghe lâu.","cue-12":"Dù có kẹt xe giữa đường sá đông đúc,","cue-13":"thì khi nghe thấy nó cũng phải khiến lòng người tĩnh lại.","cue-14":"Thế là ông đã dẫn theo toàn bộ đội ngũ,","cue-15":"lao vào tận rừng sâu và ở đó suốt hai ngày trời,","cue-16":"bẻ gãy hơn 300 cành cây khác nhau,","cue-17":"để thử từng loại gỗ,","cue-18":"âm thanh khi bẻ gãy của từng độ dày mỏng,","cue-19":"hết lần này đến lần khác,","cue-20":"thu lại hơn 300 loại âm thanh của tự nhiên.","cue-21":"Mục tiêu chỉ có một:","cue-22":"tìm ra một loại","cue-23":"âm thanh êm ái, tự nhiên, nghe một ngàn lần, mười ngàn lần","cue-24":"cũng không thấy bực bội.","cue-25":"Cuối cùng sau vô số lần thử nghiệm,","cue-26":"họ đã tìm ra.","cue-27":"Đó là lúc cành sồi nhẹ nhàng bị bẻ gãy,","cue-28":"phát ra tiếng răng rắc thật êm ái.","cue-29":"Sau đó, họ đã số hóa đoạn âm thanh đến từ khu rừng lớn này,","cue-30":"điều chỉnh lặp đi lặp lại,","cue-31":"làm mượt nó,","cue-32":"mới tạo thành tiếng bấm phím điều hướng đặc trưng của Volvo ngày nay.","cue-33":"Đó cũng là lý do vì sao","cue-34":"rất nhiều chủ xe đều nói nút bấm của Volvo","cue-35":"là nút bấm chữa lành nhất trên mạng.","cue-36":"Khi nghe thấy âm thanh đến từ tự nhiên này,","cue-37":"cho dù bên ngoài có kẹt xe đến đâu,","cue-38":"tâm trạng có bực dọc thế nào,","cue-39":"cũng có thể được xoa dịu trong chớp mắt.","cue-40":"Hóa ra sự cao cấp,","cue-41":"thực sự được giấu trong","cue-42":"những chi tiết rất dễ bị bỏ qua đó.","cue-43":"Bạn còn từng thấy trên xe hơi","cue-44":"có những thiết kế chi tiết ấm lòng nào nữa không?"}}
[/CANDIDATE_JSON]
